CREATE TABLE properties_dedup AS
SELECT * FROM (
    SELECT s.*,
           ROW_NUMBER() OVER (
               PARTITION BY lower(trim(name)), market, size_sf     -- same building = same name + market + size
               ORDER BY updated_at DESC, property_id ASC           -- keep the freshest record
           ) AS rn
    FROM stg_properties s
)
WHERE rn = 1;
